`MessageDeck` must copy its constructor inputs. It requires at least one message, every message must be a non-empty string after trimming, the cursor must be a string, and action labels and targets must be non-empty after trimming; malformed input throws `RangeError`. Stored messages, labels, and targets use their trimmed values, while the cursor is preserved verbatim. `current` initially returns the first message. `move` accepts any positive, zero, or negative integer delta, wraps in both directions, and throws `RangeError` for a non-integer without changing the index. `actions` returns fresh objects in original order. External mutations must not affect the deck.

Known-bad source:

```ts
export interface DeckAction {
  readonly label: string;
  readonly target: string;
}

export class MessageDeck {
  private readonly messages: string[];
  private readonly links: DeckAction[];
  private index = 0;
  readonly cursor: string;

  constructor(messages: readonly string[], actions: readonly DeckAction[], cursor: string) {
    if (messages.length === 0 || typeof cursor !== "string") {
      throw new RangeError("Invalid deck");
    }
    this.messages = messages.map((message) => {
      if (typeof message !== "string" || message.trim().length === 0) {
        throw new RangeError("Invalid message");
      }
      return message.trim();
    });
    this.links = actions.map((action) => {
      if (typeof action.label !== "string" || action.label.trim().length === 0
          || typeof action.target !== "string" || action.target.trim().length === 0) {
        throw new RangeError("Invalid action");
      }
      return { label: action.label.trim(), target: action.target.trim() };
    });
    this.cursor = cursor;
  }

  current(): string {
    return this.messages[this.index];
  }

  move(delta: number): string {
    if (!Number.isInteger(delta)) throw new RangeError("Delta must be an integer");
    this.index = (this.index + delta) % this.messages.length;
    return this.current();
  }

  actions(): DeckAction[] {
    return this.links.map((action) => ({ ...action }));
  }
}
```

