import { MessageDeck, type DeckAction } from './solution';

function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}
function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function throwsRange(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) {
    if (error instanceof RangeError) return;
    throw new Error(`${message}: wrong error`);
  }
  throw new Error(`${message}: expected RangeError`);
}

const messages = ['  First  ', '\tSecond\n', ' Third '];
const actions: DeckAction[] = [
  { label: ' Open ', target: ' /open ' },
  { label: 'Close', target: '/close' },
];
const deck = new MessageDeck(messages, actions, '  pointer  ');
messages[0] = 'Changed externally';
(actions[0] as { label: string; target: string }).label = 'Changed externally';
equal(deck.cursor, '  pointer  ', 'cursor is preserved verbatim');
equal(deck.current(), 'First', 'starts at trimmed first message');
deepEqual(deck.actions(), [
  { label: 'Open', target: '/open' },
  { label: 'Close', target: '/close' },
], 'copies, trims, and orders actions');

equal(deck.move(1), 'Second', 'moves forward');
equal(deck.move(0), 'Second', 'zero delta retains position');
equal(deck.move(2), 'First', 'positive movement wraps');
equal(deck.move(-1), 'Third', 'negative movement wraps backward');
equal(deck.move(-7), 'Second', 'large negative movement wraps repeatedly');
equal(deck.move(7), 'Third', 'large positive movement wraps repeatedly');

const beforeInvalidMove = deck.current();
for (const delta of [1.5, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY]) {
  throwsRange(() => deck.move(delta), `rejects non-integer delta ${delta}`);
  equal(deck.current(), beforeInvalidMove, 'invalid move does not change index');
}

const returned1 = deck.actions();
const returned2 = deck.actions();
assert(returned1 !== returned2, 'actions returns a fresh array');
assert(returned1[0] !== returned2[0], 'actions returns fresh objects');
(returned1[0] as { label: string; target: string }).label = 'Mutated';
(returned1[0] as { label: string; target: string }).target = 'Mutated';
deepEqual(deck.actions()[0], { label: 'Open', target: '/open' }, 'returned actions cannot mutate deck');

const noActions = new MessageDeck(['only'], [], '');
equal(noActions.current(), 'only', 'empty action collection is valid');
deepEqual(noActions.actions(), [], 'returns empty action collection');
equal(noActions.move(-100), 'only', 'single-message deck wraps');

const invalidCases: Array<() => unknown> = [
  () => new MessageDeck([], [], 'cursor'),
  () => new MessageDeck([''], [], 'cursor'),
  () => new MessageDeck(['   '], [], 'cursor'),
  () => new MessageDeck([4 as unknown as string], [], 'cursor'),
  () => new MessageDeck(['ok'], [{ label: '', target: '/x' }], 'cursor'),
  () => new MessageDeck(['ok'], [{ label: '   ', target: '/x' }], 'cursor'),
  () => new MessageDeck(['ok'], [{ label: 'x', target: '' }], 'cursor'),
  () => new MessageDeck(['ok'], [{ label: 'x', target: ' \t ' }], 'cursor'),
  () => new MessageDeck(['ok'], [{ label: 1, target: '/x' } as unknown as DeckAction], 'cursor'),
  () => new MessageDeck(['ok'], [], 3 as unknown as string),
];
for (const create of invalidCases) throwsRange(create, 'rejects malformed constructor input');

